html:
{# ---------------------------------------------------------
  Vehicle Inspection Log - Print Format (Jinja HTML)
  Paste this into Print Format -> HTML
---------------------------------------------------------- #}
{% set company_en = doc.company_name or "" %}
{% set company_ar = doc.company_name_arabic or "" %}
{% set phone = doc.company_phone or "" %}
{% set reg = doc.company_reg_no or "" %}
{% set logo = doc.company_logo or "" %}

{% macro tick(is_on) -%}
  {% if is_on %}✓{% else %}&nbsp;{% endif %}
{%- endmacro %}

{% macro yn_cols(status) -%}
  {# status stored like: "Sound | سليم" or "Unsound | غير سليم" #}
  {% set st = (status or "") %}
  <td class="c w12">{{ tick("Unsound" not in st) }}</td>
  <td class="c w12">{{ tick("Unsound" in st) }}</td>
{%- endmacro %}

<style>
  @page { size: A4; margin: 10mm 8mm 10mm 8mm; }
  body { font-family: Arial, sans-serif; font-size: 11.5px; color:#111; }
  .row { display:flex; gap:10px; align-items:center; }
  .sp { justify-content:space-between; }
  .box { border:1px solid #000; }
  .pad8 { padding:8px; }
  .pad6 { padding:6px; }
  .mt8 { margin-top:8px; }
  .mt10 { margin-top:10px; }
  .mt12 { margin-top:12px; }
  .h1 { font-size:15px; font-weight:700; text-align:center; line-height:1.2; }
  .ar { direction:rtl; text-align:right; }
  .small { font-size:10.5px; color:#222; }
  .lbl { font-weight:700; }
  table { width:100%; border-collapse:collapse; table-layout:fixed; }
  th, td { border:1px solid #000; padding:5px 6px; vertical-align:top; }
  th { background:#f2f2f2; font-weight:700; }
  .no-b { border:none !important; }
  .c { text-align:center; }
  .w12 { width:12%; }
  .w15 { width:15%; }
  .w20 { width:20%; }
  .w55 { width:55%; }
  .w60 { width:60%; }
  .w40 { width:40%; }
  .tight td, .tight th { padding:4px 5px; }
  .signbox { min-height:70px; }
  .hr { height:1px; background:#000; margin:8px 0; }
  .note { min-height:36px; }
  .cap { font-weight:700; }
</style>

<!-- HEADER -->
<div class="box pad8">
  <div class="row sp">
    <div style="width:95px;">
      {% if logo %}
        <img src="{{ logo | abs_url }}" style="max-width:95px; max-height:55px;">
      {% endif %}
    </div>

    <div style="flex:1;">
      <div class="h1">Daily Vehicle Inspection Log</div>
      <div class="h1 ar">سجل الفحص اليومي للسيارة</div>
    </div>

    <div style="width:200px;">
      <div class="lbl">{{ company_en }}</div>
      <div class="lbl ar">{{ company_ar }}</div>
      <div class="small mt8">
        {% if phone %}<div>Phone: {{ phone }}</div>{% endif %}
        {% if reg %}<div>Reg: {{ reg }}</div>{% endif %}
      </div>
    </div>
  </div>

  <div class="hr"></div>

  <!-- META (like paper blocks) -->
  <table class="tight">
    <tr>
      <td class="w20"><span class="lbl">Inspection No</span></td>
      <td class="w30">{{ doc.name }}</td>
      <td class="w20"><span class="lbl">Date</span> <span class="ar lbl">التاريخ</span></td>
      <td class="w30">{{ doc.inspection_date }}</td>
    </tr>
    <tr>
      <td><span class="lbl">Driver</span> <span class="ar lbl">السائق</span></td>
      <td>{{ doc.driver }}</td>
      <td><span class="lbl">Vehicle</span> <span class="ar lbl">المركبة</span></td>
      <td>{{ doc.vehicle }}</td>
    </tr>
  </table>
</div>

{# -------- Group rows by section/category (as on paper) -------- #}
{% set groups = {} %}
{% for r in doc.items %}
  {% set sec = (r.section or r.category or "Checklist") %}
  {% if sec not in groups %}{% set _ = groups.update({sec: []}) %}{% endif %}
  {% set _ = groups[sec].append(r) %}
{% endfor %}

{# -------- Render each section as a table -------- #}
{% for sec, rows in groups.items() %}
  <div class="box mt10">
    <div class="pad6 cap">
      {{ sec }}
      <span class="ar" style="float:right;">
        {# optional: show Arabic section titles if you stored bilingual in section options #}
      </span>
    </div>

    <table class="tight">
      <thead>
        <tr>
          <th class="w60">Item | <span class="ar">البند</span></th>
          <th class="c w12">Sound<br><span class="ar">سليم</span></th>
          <th class="c w12">Unsound<br><span class="ar">غير سليم</span></th>
          <th class="w16">Notes | <span class="ar">ملاحظات</span></th>
        </tr>
      </thead>
      <tbody>
        {% for r in rows %}
          <tr>
            <td>
              {{ r.item or "" }}
              {% if not r.item and r.item_en %}{{ r.item_en }}{% endif %}
            </td>

            {{ yn_cols(r.status) }}

            <td>{{ r.notes or "" }}</td>
          </tr>
        {% endfor %}
      </tbody>
    </table>
  </div>
{% endfor %}

<!-- DECLARATION + NOTES -->
<div class="box mt10 pad8">
  <div class="row sp">
    <div style="flex:1;">
      <div class="lbl">Declaration</div>
      <div class="ar lbl">إقرار</div>
      <div class="small">
        {{ doc.declaration or "I confirm the above inspection is correct. | أقر بأن بيانات الفحص أعلاه صحيحة." }}
      </div>
    </div>

    <div style="width:42%;">
      <div class="lbl">Overall Notes</div>
      <div class="ar lbl">ملاحظات عامة</div>
      <div class="box pad6 note">{{ doc.overall_notes or "" }}</div>
    </div>
  </div>
</div>

<!-- SIGNATURES (bottom like paper) -->
<div class="row sp mt12">
  <div class="box pad8 w40 signbox" style="width:49%;">
    <div class="lbl">Driver Signature</div>
    <div class="ar lbl">توقيع السائق</div>
    <div class="mt8">
      {% if doc.driver_signature %}
        <img src="{{ doc.driver_signature }}" style="max-height:45px;">
      {% else %}
        <div class="small">__________________________</div>
      {% endif %}
    </div>
    <div class="mt8 small">
      <span class="lbl">Name:</span> {{ doc.driver_name_text or doc.driver or "" }}
    </div>
  </div>

  <div class="box pad8 w40 signbox" style="width:49%;">
    <div class="lbl">Supervisor Signature</div>
    <div class="ar lbl">توقيع المشرف</div>
    <div class="mt8">
      {% if doc.supervisor_signature %}
        <img src="{{ doc.supervisor_signature }}" style="max-height:45px;">
      {% else %}
        <div class="small">__________________________</div>
      {% endif %}
    </div>
    <div class="mt8 small">
      <span class="lbl">Name:</span> {{ doc.supervisor_name_text or "" }}
    </div>
  </div>
</div>
